internal sealed record ForgingMaterialRule(
    uint ItemId,
    uint? NextItemId,
    int MaterialType,
    int? MaterialProyAdd,
    IReadOnlyList<int> Round)
{
    public int ProbabilityBonus => MaterialProyAdd ?? 0;

    public bool AllowsRound(int round)
    {
        if (Round.Count == 0)
        {
            return true;
        }

        if (Round.Count == 2 && Round[0] <= Round[1])
        {
            return round >= Round[0] && round <= Round[1];
        }

        return Round.Contains(round);
    }
}

